import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.DToEn73J.js";const m=JSON.parse('{"title":"上下文工程","description":"","frontmatter":{"title":"上下文工程","chapter":"3.1","order":1,"summary":"通过结构化编排 system prompt、工具描述与 few-shot 示例的优先级，在有限 Context Window 内最大化模型决策质量。"},"headers":[],"relativePath":"03-context-memory/context-engineering.md","filePath":"03-context-memory/context-engineering.md","lastUpdated":1788254264000}'),n={name:"03-context-memory/context-engineering.md"};function i(l,t,d,s,c,h){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="上下文工程" tabindex="-1">上下文工程 <a class="header-anchor" href="#上下文工程" aria-label="Permalink to &quot;上下文工程&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>上下文工程是在 Agent Loop 每次推理前，决定“往 Context Window 里放什么、以什么顺序、放多少”的系统性设计，目标是用最少的 token 换来最高的下游动作正确率。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><p><strong>System prompt 区块结构</strong>（从高到低固定排序）：</p><ol><li>身份/目标（role + objective）</li><li>全局约束（Guardrails、不可违反的规则）</li><li>工具使用协议（ReAct 输出格式约定）</li><li>领域知识与当前会话元信息</li><li>动态注入区（工具结果、Memory 召回、Plan）</li></ol><p><strong>工具描述的信息密度</strong>：每个 Tool 描述只保留三段——做什么、何时用、参数关键约束。把长文档拆到工具自身的 <code>description</code> 而非塞进系统提示；冗余描述会稀释注意力。</p><p><strong>few-shot 示例摆放</strong>：放在工具协议之后、动态区之前；数量 1–3 条即可，优先覆盖高频易错路径。示例过多会挤占 Context Window 并诱导模式拷贝。</p><p>优先级排序原则：</p><table tabindex="0"><thead><tr><th>区块</th><th>优先级</th><th>取舍</th></tr></thead><tbody><tr><td>全局约束/Guidrails</td><td>最高</td><td>永远满血保留</td></tr><tr><td>当前任务与 Plan</td><td>高</td><td>压缩而非丢弃</td></tr><tr><td>工具结果</td><td>中</td><td>超长则截断/摘要</td></tr><tr><td>历史对话</td><td>低</td><td>可被 compaction 替换</td></tr></tbody></table><h2 id="为什么" tabindex="-1">为什么 <a class="header-anchor" href="#为什么" aria-label="Permalink to &quot;为什么&quot;">​</a></h2><p>不做优先级排序，模型会在长会话中被早期低价值信息占据 Context Window，导致后期工具调用退化、约束被遗忘。上下文是有限预算，编排顺序直接决定有效注意力分配。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li>把全部工具文档堆进 system prompt，造成“描述噪声淹没指令”。</li><li>用大量 few-shot 教格式，反而让模型忽视动态工具结果。</li></ul><h2 id="业界实现对照" tabindex="-1">业界实现对照 <a class="header-anchor" href="#业界实现对照" aria-label="Permalink to &quot;业界实现对照&quot;">​</a></h2><ul><li>Claude Agent SDK：system prompt 与 tool 描述分离，支持动态 context 注入（<a href="https://docs.anthropic.com/en/docs/agents-and-tools/agent-sdk/overview" target="_blank" rel="noreferrer">docs</a>）。</li><li>LangChain：通过 <code>SystemMessage</code> + <code>MessagesPlaceholder</code> 控制上下文装配顺序（<a href="https://python.langchain.com/docs/concepts/prompt_templates/" target="_blank" rel="noreferrer">docs</a>）。</li></ul><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/fk-ai-agent/03-context-memory/context-window">Context Window 预算分配</a></li><li><a href="/fk-ai-agent/03-context-memory/session-state">会话状态与恢复</a></li><li><a href="/fk-ai-agent/01-agent-basics/budget-control">预算控制与限流</a></li><li><a href="/fk-ai-agent/01-agent-basics/agent-loop">Agent Loop 基础</a></li></ul><hr><p><em>最后核实日期：2026-08-26</em></p>',20)])])}const g=e(n,[["render",i]]);export{m as __pageData,g as default};
